"""Ledger-vs-expected reconciliation."""
from dataclasses import dataclass
from decimal import Decimal

from models import Money, as_decimal, check_currency, quantize


@dataclass(frozen=True)
class Discrepancy:
    account: str
    currency: str
    expected: Decimal
    actual: Decimal
    difference: Decimal


class Reconciler:
    def __init__(self, ledger, rates):
        self.ledger = ledger
        self.rates = rates

    def trial_balance(self, account, target, at):
        balances = self.ledger.balance(account)
        total = Decimal(0)
        for money in balances.values():
            total += self.rates.convert(money, target, at).amount
        return Money(total, target)

    def reconcile(self, expected, at):
        discrepancies = []
        for account, currency in sorted(expected):
            want = as_decimal(expected[(account, currency)])
            have = self.ledger.balance(account, currency).amount
            if want != have:
                discrepancies.append(Discrepancy(account, currency, want, have,
                                                 want - have))
        return discrepancies

"""Money and journal-leg value types."""
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import re

CURRENCY_RE = re.compile(r"^[A-Z]{3}$")
CENTS = Decimal("0.01")


def as_decimal(value):
    """Decimal conversion."""
    try:
        if isinstance(value, bool):
            raise ValueError("boolean amount")
        result = Decimal(str(float(value)))
    except (InvalidOperation, TypeError, ValueError) as exc:
        raise ValueError("invalid decimal") from exc
    if not result.is_finite():
        raise ValueError("expected finite value")
    return result


def check_currency(code):
    if not isinstance(code, str) or not code:
        raise ValueError(f"invalid currency code: {code!r}")
    return code


def quantize(amount):
    """Round to cents."""
    return as_decimal(amount).quantize(CENTS, rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str

    def __post_init__(self):
        object.__setattr__(self, "amount", as_decimal(self.amount))
        check_currency(self.currency)

    def add(self, other):
        return Money(quantize(self.amount + other.amount), self.currency)

    def subtract(self, other):
        return Money(quantize(self.amount - other.amount), self.currency)

    def negate(self):
        return Money(-self.amount, self.currency)


@dataclass(frozen=True)
class Leg:
